def max_product(num_str: str, N: int, K: int) -> int:
    # If the string is empty or length is zero
    if N == 0 or not num_str:
        return 0
    # If no multiplication signs are to be inserted
    if K == 0:
        return int(num_str)
    # It is impossible to place more than N-1 multiplication signs
    K = min(K, N - 1)

    # dp[i][k] = maximum product for prefix of length i using k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # Identity for multiplication

    for i in range(1, N + 1):  # current prefix length
        for k in range(0, min(K, i - 1) + 1):  # number of multiplications used
            best = 0
            for j in range(0, i):  # split point: last number is num_str[j:i]
                part = int(num_str[j:i])
                if j == 0:
                    # No previous part
                    if k == 0:
                        best = max(best, part)
                else:
                    if k > 0 and dp[j][k - 1] != 0:
                        best = max(best, dp[j][k - 1] * part)
            dp[i][k] = best
    return dp[N][K] if dp[N][K] != 0 else int(num_str)  # fallback if no multiplication possible

def max_product(num_str: str, N: int, K: int) -> int:
    # If the number of multiplications requested exceeds the number of possible gaps, return 0
    if K > N - 1:
        return 0

    # dp[i][k] = maximum product for the prefix num_str[:i+1] using k multiplications
    dp = [[0] * (K + 1) for _ in range(N)]

    # Base case: no multiplication, take the whole prefix as one number
    for i in range(N):
        dp[i][0] = int(num_str[:i + 1])

    # Build up the DP table
    for k in range(1, K + 1):
        # At least k splits require i >= k (since we need at least k+1 parts)
        for i in range(k, N):
            max_prod = 0
            # Partition point j separates the last part from the previous parts
            for j in range(k - 1, i):
                left_prod = dp[j][k - 1]
                right_num = int(num_str[j + 1:i + 1])
                prod = left_prod * right_num
                if prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    return dp[N - 1][K]

def max_product(num_str: str, N: int, K: int) -> int:
    n = N
    if n == 0:
        return 0
    # dp[i][k] = maximum product for first i digits with k multiplication signs
    dp = [[0] * (K + 1) for _ in range(n + 1)]
    # base case: no multiplication sign
    for i in range(1, n + 1):
        dp[i][0] = int(num_str[:i])
    # fill table for k >= 1
    for k in range(1, K + 1):
        for i in range(k + 1, n + 1):  # need at least k+1 digits to place k signs
            best = 0
            for j in range(k, i):
                part = int(num_str[j:i])
                val = dp[j][k - 1] * part
                if val > best:
                    best = val
            dp[i][k] = best
    return dp[n][K] if K <= n - 1 else 0

