def verify_isbn(isbn: str) -> str:
    """
    Verify the correctness of an ISBN-10 number and correct it if necessary.

    Parameters:
    isbn (str): An ISBN-10 string in the format 'x-xxx-xxxxx-x', where the
                last group may contain 'X' as the checksum character.

    Returns:
    str: "Right" if the ISBN checksum is correct, otherwise the corrected ISBN
         number in the same hyphenated format.

    Raises:
    ValueError: If the input does not conform to the expected ISBN-10 format.
    """
    # Split the ISBN into its parts separated by hyphens
    parts = isbn.split('-')
    if len(parts) != 4:
        raise ValueError("ISBN must have four parts separated by hyphens")

    # Combine all parts into a single string of characters
    digits = ''.join(parts)
    if len(digits) != 10:
        raise ValueError("ISBN must contain exactly 10 characters (including possible 'X')")

    # Calculate checksum using ISBN-10 algorithm
    def char_value(c: str) -> int:
        return 10 if c.upper() == 'X' else int(c)

    total = 0
    for idx, char in enumerate(digits):
        if idx == 9 and char.upper() == 'X':
            value = 10
        elif char.isdigit():
            value = int(char)
        else:
            raise ValueError("ISBN contains invalid characters")
        total += (idx + 1) * value

    if total % 11 == 0:
        return "Right"

    # Compute correct checksum digit
    sum_first_9 = sum((i + 1) * char_value(digits[i]) for i in range(9))
    correct_digit = None
    for d in range(11):
        if (sum_first_9 + 10 * d) % 11 == 0:
            correct_digit = d
            break

    if correct_digit is None:
        raise RuntimeError("Failed to compute a valid checksum")

    checksum_char = 'X' if correct_digit == 10 else str(correct_digit)

    corrected_parts = parts[:3] + [checksum_char]
    return '-'.join(corrected_parts)

