def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Prepare list of possible aisle positions
    row_positions = list(range(1, M))          # aisles between row i and i+1
    col_positions = list(range(1, N))          # aisles between column j and j+1

    best_count = -1
    best_rows = ()
    best_cols = ()

    # Generate all combinations of aisles
    for h_rows in combinations(row_positions, K):
        h_set = set(h_rows)
        for v_cols in combinations(col_positions, L):
            v_set = set(v_cols)
            count = 0
            for r1, c1, r2, c2 in chatting_pairs:
                separated = False
                if r1 != r2:
                    # Check if an aisle between rows separates them
                    # The aisle index i separates rows if one is <= i and the other > i
                    low, high = min(r1, r2), max(r1, r2)
                    for i in h_set:
                        if low <= i < high:
                            separated = True
                            break
                if not separated and c1 != c2:
                    low, high = min(c1, c2), max(c1, c2)
                    for j in v_set:
                        if low <= j < high:
                            separated = True
                            break
                if separated:
                    count += 1
            if count > best_count:
                best_count = count
                best_rows = h_rows
                best_cols = v_cols

    hr_str = ' '.join(map(str, sorted(best_rows))) if K > 0 else ''
    vr_str = ' '.join(map(str, sorted(best_cols))) if L > 0 else ''
    return hr_str, vr_str

def count_passing_ways(n: int, m: int) -> int:
    current = [0] * n
    current[0] = 1
    for _ in range(m):
        next_state = [0] * n
        for pos, ways in enumerate(current):
            if ways:
                next_state[(pos + 1) % n] += ways
                next_state[(pos - 1) % n] += ways
        current = next_state
    return current[0]

