def polynomial_to_string(n, coeffs):
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if n < 0 or not coeffs or len(coeffs) != n + 1:
        raise ValueError("Invalid input: n and coeffs length mismatch or negative degree")

    result = ""
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign part
        if first_term:
            sign = "" if coeff > 0 else "-"
        else:
            sign = "+" if coeff > 0 else "-"

        abs_coeff = abs(coeff)

        # Determine coefficient string part
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            if abs_coeff == 1:
                coeff_str = ""
            else:
                coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_part = f"x^{degree}"
        elif degree == 1:
            var_part = "x"
        else:
            var_part = ""

        term = f"{sign}{coeff_str}{var_part}"
        result += term
        first_term = False

    if not result:
        return "0"
    return result

