def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ''

    # Map each character to its index in the inorder string for O(1) lookups
    inorder_index = {char: idx for idx, char in enumerate(inorder)}

    def build(i_start: int, i_end: int, p_start: int, p_end: int) -> str:
        if i_start > i_end:
            return ''
        # The root is the last element of the current postorder segment
        root = postorder[p_end]
        idx = inorder_index[root]
        # Number of nodes in the left subtree
        left_size = idx - i_start
        # Recursively build left and right subtrees
        left_pre = build(i_start, idx - 1, p_start, p_start + left_size - 1)
        right_pre = build(idx + 1, i_end, p_start + left_size, p_end - 1)
        # Preorder is root + left preorder + right preorder
        return root + left_pre + right_pre

    n = len(inorder)
    return build(0, n - 1, 0, n - 1)

def string_transformation(A: str, B: str, rules: list) -> int | str:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps if
    possible, otherwise returns "NO ANSWER!".
    """
    if A == B:
        return 0

    max_depth = 10
    queue = [(A, 0)]
    visited = {A}

    while queue:
        current, depth = queue.pop(0)

        if depth >= max_depth:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return depth + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, depth + 1))
                start = idx + 1

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    from collections import deque

    start = str(n)
    visited = {start}
    queue = deque([start])

    # Convert rules to string for easy comparison
    string_rules = [(str(src), str(dst)) for src, dst in rules]

    while queue:
        cur = queue.popleft()
        for src, dst in string_rules:
            # For each occurrence of src digit in cur
            for i, ch in enumerate(cur):
                if ch == src:
                    new_num = cur[:i] + dst + cur[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

