    def evaluate(stmt: str, speaker: str) -> bool:
        # Remove trailing punctuation and normalize
        clean = stmt.strip().rstrip('.')
        lowered = clean.lower()

        # Patterns for personal statements
        if lowered == "i am guilty":
            return speaker == scenario
        if lowered in ("i am not guilty", "i am innocent"):
            return speaker != scenario

        # Regex for statements referencing other participants
        match_guilty = re.match(r'^([a-zA-Z]+)\s+is\s+guilty$', lowered)
        if match_guilty:
            name = match_guilty.group(1).upper()
            return name == scenario

        match_not_guilty = re.match(r'^([a-zA-Z]+)\s+is\s+(not guilty|innocent)$', lowered)
        if match_not_guilty:
            name = match_not_guilty.group(1).upper()
            return name != scenario

        # If statement doesn't match known patterns, assume it's true
        return True

    # Iterate over all speakers and their statements
    for speaker, stmts in statements.items():
        is_liar = speaker in liar_count
        for stmt in stmts:
            # Skip statements mentioning the day of the week
            if any(day.lower() in stmt.lower() for day in days_of_week):
                continue
            truth = evaluate(stmt, speaker)
            if is_liar and truth:
                return False         # Liars cannot speak truth
            if not is_liar and not truth:
                return False         # Truthful speakers cannot lie
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
