def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to evaluate truth of a statement
    def is_truthful(speaker: str, stmt: str) -> bool:
        stmt_str = stmt.strip().lower()
        # Ignore statements that mention a day of the week
        for day in days_of_week:
            if day.lower() in stmt_str:
                return None  # indeterminate, ignore

        # Self statements
        if stmt_str == "i am guilty." or stmt_str == "i am guilty":
            return speaker == scenario
        if stmt_str == "i am not guilty." or stmt_str == "i am not guilty":
            return speaker != scenario

        # Statements about other participants
        if " is guilty." in stmt_str or " is guilty" in stmt_str:
            name = stmt_str.split(" is guilty")[0].strip().upper()
            return name == scenario
        if " is not guilty." in stmt_str or " is not guilty" in stmt_str:
            name = stmt_str.split(" is not guilty")[0].strip().upper()
            return name != scenario

        # If statement doesn't match known patterns, treat as indeterminate
        return None

    # Iterate through each participant and their statements
    for participant, stmts in statements.items():
        for stmt in stmts:
            truth_value = is_truthful(participant, stmt)
            if truth_value is None:
                continue  # Ignore this statement (day of week or unknown pattern)

            if participant in liar_count:
                # Liars must always lie, so truth_value must be False
                if truth_value:
                    return False
            else:
                # Truthful participants must always tell the truth
                if not truth_value:
                    return False

    return True

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan[i] = total
    return catalan[n]

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if not areas:
        return max(l, 0)
    # sort intervals by starting point
    sorted_areas = sorted(areas, key=lambda x: x[0])
    merged: List[Tuple[int, int]] = []
    for start, end in sorted_areas:
        if start >= end:
            continue  # ignore empty or invalid intervals
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    # compute total cleared length
    total_cleared = sum(end - start for start, end in merged)
    remaining = l - total_cleared
    return remaining if remaining > 0 else 0

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Dynamic programming table: dp[i] is True if volume i can be achieved
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in volumes:
        if vol > V:
            # Skip items that cannot fit individually
            continue
        # Process in reverse to avoid reuse of the same item
        for i in range(V, vol - 1, -1):
            if dp[i - vol]:
                dp[i] = True

    # Find the largest achievable volume that does not exceed the box capacity
    max_occupied = max(i for i, achievable in enumerate(dp) if achievable)
    # The remaining space is the difference between capacity and occupied volume
    return V - max_occupied

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # DP array where dp[j] is True if a subset sums to j
    dp = [False] * (V + 1)
    dp[0] = True

    for i in range(n):
        vol = volumes[i]
        if vol > V:
            continue
        # Iterate backwards to avoid reusing the same item
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True

    # Find the largest achievable volume not exceeding V
    max_occupied = max(idx for idx, ok in enumerate(dp) if ok)
    return V - max_occupied

def min_remaining_space(V: int, n: int, volumes) -> int:
    """Return the minimum remaining space in a box of capacity V after packing a subset of n items.

    Uses a 0/1 knapsack (subset-sum) DP to find the largest volume <= V that can be filled.
    """
    dp = [False] * (V + 1)
    dp[0] = True
    for i in range(n):
        w = volumes[i]
        if w > V:
            continue
        for cap in range(V, w - 1, -1):
            if dp[cap - w]:
                dp[cap] = True
    for cap in range(V, -1, -1):
        if dp[cap]:
            return V - cap
    return V  # No items can be placed

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for cap in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp[j]) % MOD
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            lo = j - cap - 1
            if lo >= 0:
                new_dp[j] = (prefix[j] - prefix[lo]) % MOD
            else:
                new_dp[j] = prefix[j]
        dp = new_dp
    return dp[m] % MOD

def mod_inverse(a, b):
    """
    Calculate the modular multiplicative inverse of a modulo b.

    Parameters:
    a (int): The integer whose modular inverse is to be found.
    b (int): The modulus with respect to which the inverse is sought.

    Returns:
    int or None: The modular inverse of a modulo b if it exists, otherwise None.
    """
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None  # No modular inverse if a and b are not coprime
    return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    best_day = 0
    for day_index, (school, extra) in enumerate(schedule, start=1):
        total_hours = school + extra
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                best_day = day_index
    return best_day

