    Compute the minimum number of students that must leave so that the remaining
    heights form a strictly increasing sequence up to a peak and then a strictly
    decreasing sequence thereafter.

    The problem reduces to finding the longest bitonic subsequence.
    """
    n = len(heights)
    if n <= 2:
        return 0  # Already bitonic or trivial

    # Longest strictly increasing subsequence lengths ending at each i
    lis_left = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis_left[j] + 1 > lis_left[i]:
                lis_left[i] = lis_left[j] + 1

    # Longest strictly increasing subsequence lengths starting at each i
    # (which corresponds to strictly decreasing subsequence ending at i when read back)
    lis_right = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lis_right[j] + 1 > lis_right[i]:
                lis_right[i] = lis_right[j] + 1

    # Compute longest bitonic subsequence length
    longest_bitonic = 0
    for i in range(n):
        # lis_left[i] counts the increasing part including i
        # lis_right[i] counts the decreasing part including i
        current_length = lis_left[i] + lis_right[i] - 1
        if current_length > longest_bitonic:
            longest_bitonic = current_length

    # Minimum deletions = total students - longest bitonic subsequence length
    return n - longest_bitonic

