def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is a sequence that strictly increases up to a point and then strictly decreases.
    This is equivalent to finding the longest bitonic subsequence (strict).

    :param heights: List[int] - student heights
    :return: int - minimum number of students that need to leave
    """
    n = len(heights)
    if n <= 1:
        return 0

    # Longest Increasing Subsequence ending at each position
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest Decreasing Subsequence starting at each position
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Max length of a bitonic subsequence
    max_len = 0
    for i in range(n):
        # subtract 1 to avoid double counting height[i]
        total = lis[i] + lds[i] - 1
        if total > max_len:
            max_len = total

    return n - max_len

def hanoi_double_iterative(n: int) -> int:
    """Calculate the minimum number of moves required to solve the double-disc Hanoi Towers problem for n pairs of discs."""
    if n <= 0:
        return 0
    moves = 2  # base case for n = 1
    for _ in range(2, n + 1):
        moves = 2 * moves + 2
    return moves
